window.AUTH=window.AUTH||{};window.AUTH["17-5716"]={"d":"17-5716","id":"2017/17-5716","n":"Koons v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioners Timothy D. Koons, et al.","date":"2018-01-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-5716/28736/20180122155719999_17-5716ts.pdf","side":"pet","n":62},{"k":"respondent","label":"Brief of respondent United States","date":"2018-02-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-5716/36186/20180221203423164_17-5716bsUnitedStates.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioners Timothy D. Koons, et al.","date":"2018-03-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-5716/38747/20180313131614488_17-5716rb.pdf","side":"pet","n":33}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"by":{"0":"30"}},{"t":"case","label":"Bell v. United States","cite":"349 U.S. 81","y":1955,"id":"scdb/1954-072","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"if Congress does not fix the punishment for a federal crime clearly and without ambiguity, doubt will be resolved against [the government].","cite":"349 U.S. 81, 84"}]},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"by":{"0":"42"}},{"t":"case","label":"Braxton v. United States","cite":"500 U.S. 344","y":1991,"id":"1990/90-5358","sc":1,"by":{"0":"36, 38","1":"50"}},{"t":"case","label":"Busic v. United States","cite":"446 U.S. 398","y":1980,"id":"1979/78-6020","sc":1,"by":{"0":"42"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"by":{"0":"24, 35, 36","1":"passim","2":"19"},"q":[{"src":"brief","b":0,"text":"‘the amended guideline range that would have been applicable to the defendant’ had the relevant amendment been in effect at the time of the initial sentencing.","cite":"560 U.S. 817, 827"},{"src":"brief","b":0,"text":"represents a congressional act of lenity intended to give prisoners the benefit of later enacted adjustments to the judgments reflected in the Guidelines.","cite":"560 U.S. 817, 828"},{"src":"brief","b":1,"text":"promulgate Sentencing Guidelines and to issue policy statements regarding the Guidelines’ application.","cite":"560 U.S. 817, 820"},{"src":"brief","b":1,"text":"also charged the Commission with periodically reviewing and revising the Guidelines.","cite":"560 U.S. at 820"},{"src":"argument","who":"Mr. Feigin","text":"They're wrong the district judge made an error, and I'll get to that in one second, but even if the district judge had made an error, this Court's decision in Dillon makes quite clear that Section 3582(c)(2) proceedings are not for error correction."},{"src":"argument","who":"Mr. Feigin","text":"I'm not sure that we could, Your Honor, because the Court made clear in Dillon it's not a complete resentencing. You essentially do everything the same way you did at the first sentencing and just substitute in the -"},{"src":"argument","who":"Mr. Feigin","text":"So Dillon addresses the fact that this isn't a full resentencing proceeding. And I was responding to Justice Kagan's suggestion that the government had effectively acquiesced to Section 3582(c)(2) relief when it, in a case, again, not this case, where substantial assistance sentencing was done improperly and the government hadn't appealed."}]},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"by":{"0":"passim","1":"5, 24, 28, 55","2":"3, 7, 10, 13"},"q":[{"src":"brief","b":0,"text":"are relieved of application of a mandatory minimum.","cite":"567 U.S. at 285"},{"src":"brief","b":0,"text":"create new anomalies—new sets of disproportionate sentences—not previously present.","cite":"567 U.S. 260, 278"},{"src":"argument","who":"Mr. Fisher","text":"As the Court put it in Dorsey, what the court does when it grants a substantial assistant motion is it lets the defendant escape the binding effect of the mandatory minimum."},{"src":"argument","who":"Mr. Fisher","text":"And that special situation, as the Court put it in Dorsey, allows the defendant to escape the minimum. Another way to think about it, Justice Ginsburg, is we're not doing any -- we're not avoiding any trumping problem, because we have two statutes that have to work together."},{"src":"argument","who":"Mr. Fisher","text":"And what's what the Court itself said in Dorsey. In Dorsey, the Court said there are two ways for a judge and a defendant to escape a mandatory minimum."}]},{"t":"case","label":"Freeman v. United States","cite":"564 U.S. 522","y":2011,"id":"2010/09-10245","sc":1,"by":{"0":"passim","1":"passim","2":"14, 16, 17, 21"},"q":[{"src":"brief","b":0,"text":"[t]he Guidelines provide a framework or starting point—a basis, in the commonsense meaning of the term—for the judge’s exercise of discretion.","cite":"564 U.S. at 529"},{"src":"brief","b":0,"text":"Even if the sentencing judge sees a reason to vary from the Guidelines, ‘if the judge uses the sentencing range as the beginning point to explain the decision to deviate from it, then the Guidelines are in a real sense a basis for the sentence.’","cite":"564 U.S. at 529"},{"src":"brief","b":1,"text":"‘based on’ his statutory mandatory minimum sentence and his substantial assistance.","cite":"564 U.S. 522"},{"src":"brief","b":1,"text":"‘a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission.’","cite":"564 U.S. 522, 526-527"},{"src":"brief","b":2,"text":"permit[s] the district court to revisit a prior sentence to whatever extent the sentencing range in question","cite":"564 U.S. 522, 530"},{"src":"brief","b":2,"text":"a relevant part of the analytic framework the judge use[s] to determine the sentence,","cite":"564 U.S. at 530"}]},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"by":{"0":"3, 21","1":"20"},"q":[{"src":"brief","b":0,"text":"a district court should begin all sentencing proceedings by correctly calculating the applicable Guidelines range.","cite":"552 U.S. 38, 49"},{"src":"argument","who":"Mr. Fisher","text":"And so, in all the other scenarios where the judge does what is more commonly done in -- in a Gall-type situation or all the other situations this Court has seen where you start with the guidelines, and -- and -- and our very case illustrates you usually land within the guidelines, or you vary from the guidelines for one reason or another."}]},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"by":{"0":"39"}},{"t":"case","label":"Melendez v. United States","cite":"518 U.S. 120","y":1996,"id":"1995/95-5661","sc":1,"by":{"0":"30","1":"passim","2":"passim"},"q":[{"src":"brief","b":0,"text":"ultimately [i]s not subject to any statutory minimum sentence, because the district court granted a substantial assistance motion in his case.","cite":"518 U.S. 120"},{"src":"brief","b":1,"text":"a departure below the statutory minimum,","cite":"518 U.S. at 130"},{"src":"brief","b":1,"text":"the relevant parts of the statutes merely charge the Commission with constraining the district court’s discretion in choosing a specific sentence after the Government moves for a departure below the statutory minimum.","cite":"518 U.S. at 129"},{"src":"argument","who":"Mr. Fisher","text":"And if I could add one other thing to your question, Justice Sotomayor, that I think puts this all together, it's to refer to the Court's opinion in Melendez."},{"src":"argument","who":"Mr. Feigin","text":"So what that sentence does, Your Honor, is it notes that the guidelines are going to guide the court's discretion, which is exactly what 5K1.1 does, and it's exactly what this Court recognized 5K1.1 does in its decision in Melendez, if you look at pages 128 to 129 and Note 10."},{"src":"argument","who":"Mr. Feigin","text":"I -- I -- I do think this was effectively settled in Melendez, Your Honor, but addressed as a matter of first principles. I think the reason for that is if we now look at 994(n), which is on page 14a of the government's brief, 994(n) says: the Commission shall assure that the guidelines,\" writ large, \"reflect the general appropriateness of imposing a lower sentence than would otherwise be imposed, including a sentence that is lower than that established by a statute as a minimum sentence, to take into account a defendant's substantial assistance.\" So just to address your question, Mr."}]},{"t":"case","label":"Michigan v. E.P.A.","cite":"135 S. Ct. 2699","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2699/","sc":1,"by":{"0":"36"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"137 S. Ct. 1702","y":2017,"id":"2016/15-457","sc":1,"by":{"0":"38"}},{"t":"case","label":"Mohawk Indus. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"by":{"0":"38"}},{"t":"case","label":"Peugh v. United States","cite":"569 U.S. 530","y":2013,"id":"2012/12-62","sc":1,"by":{"0":"21, 22","1":"26, 47"}},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"by":{"0":"21"}},{"t":"case","label":"Simpson v. United States","cite":"435 U.S. 6","y":1978,"id":"1977/76-5796","sc":1,"by":{"0":"42"}},{"t":"case","label":"Swint v. Chambers Cty. Comm’n","cite":"514 U.S. 35","y":1995,"id":"1994/93-1636","sc":1,"by":{"0":"38"}},{"t":"case","label":"United States v. Becton","cite":"593 Fed. Appx. 469","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./593/469/","by":{"0":"31, 31"}},{"t":"case","label":"United States v. Billue","cite":"576 F.3d 898","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/576/898/","by":{"0":"passim","1":"8, 13"}},{"t":"case","label":"United States v. Bogdan","cite":"835 F.3d 805","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/835/805/","by":{"0":"13"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"by":{"0":"30","1":"20","2":"10"},"q":[{"src":"argument","who":"Mr. Fisher","text":"I think that's the only way a judge might work around that, is to say after Booker, the judge is allowed to set the guidelines entirely aside."},{"src":"argument","who":"Justice Alito","text":"Yeah, so we are after Booker. So that's what the judge says. Then what?"}]},{"t":"case","label":"United States v. Byers","cite":"561 F.3d 825","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/561/825/","by":{"0":"26"}},{"t":"case","label":"United States v. C.D.","cite":"848 F.3d 1286","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/1286/","by":{"0":"18","1":"16"}},{"t":"case","label":"United States v. Freeman","cite":"586 Fed. Appx. 237","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./586/237/","by":{"0":"40, 41"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"0":"42","2":"22"}},{"t":"case","label":"United States v. Rodriguez-Soriano","cite":"855 F.3d 1040","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/855/1040/","by":{"0":"18","1":"47"}},{"t":"case","label":"United States v. Williams","cite":"808 F.3d 253","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/808/253/","by":{"0":"13, 18, 40","2":"12"}},{"t":"case","label":"United States v. Wills","cite":"35 F.3d 1192","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/35/1192/","by":{"0":"30","2":"10"}},{"t":"case","label":"United States v. Winebarger","cite":"664 F.3d 388","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/664/388/","by":{"0":"33, 34","1":"32, 33, 37, 38, 39, 43"},"q":[{"src":"brief","b":0,"text":"the nature and extent of the assistance rendered.","cite":"664 F.3d 388, 395"},{"src":"brief","b":1,"text":"Presumably, Congress could have written the first sentence of § 3553(e) to read, ‘Upon motion of the Government indicating that a defendant has given substantial assistance in the investigation or prosecution of another person who has committed an offense, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence.’","cite":"664 F.3d at 392"},{"src":"argument","who":"Mr. Fisher","text":"So I think if we grant the government all of its legal arguments, even there, as the Third Circuit said in Winebarger, the guideline has some effect on the ultimate sentence, at least to the degree, as Justice Breyer was pointing out, the district judge should have another look."}]},{"t":"case","label":"United States v. Wren","cite":"706 F.3d 861","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/706/861/","by":{"0":"42","2":"19, 20"},"q":[{"src":"brief","b":2,"text":"means that the new [§ 2D1.1] range must not be reset to equal the presumptive statutory minimum.","cite":"706 F.3d 861, 864"}]},{"t":"case","label":"Wade v. United States","cite":"504 U.S. 181","y":1992,"id":"1991/91-5771","sc":1,"by":{"0":"20, 26"},"q":[{"src":"brief","b":0,"text":"empowers district courts, ‘[u]pon motion of the Government,’ to impose a sentence below the statutory minimum to reflect a defendant’s ‘substantial assistance in the investigation or prosecution of another person who has committed an offense.’","cite":"504 U.S. 181, 182"}]},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"30"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5","1":"4"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)"],"by":{"0":"5"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)(4)","(a)(6)","(e)","(f)","(a)","(a)(2)","(a)(4)(A)","(a)(5)","(a)(5)(A)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 20, 39, passim, 27","1":"40, 40, passim, passim, passim, passim, passim, passim","2":"12, 3, passim, 7, 8"},"q":[{"src":"brief","b":0,"text":"Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code.","cite":"18 U.S.C. § 3553(e)"},{"src":"brief","b":0,"text":"the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant’s substantial assistance in the investigation or prosecution of another person who has committed an offense.","cite":"18 U.S.C. § 3553(e)"},{"src":"brief","b":1,"text":"limited authority provided in the first sentence of § 3553(e) is only to ‘impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant’s substantial assistance.’","cite":"18 U.S.C. 3553(e)"},{"src":"brief","b":1,"text":"any pertinent policy statement * * * issued by the Sentencing Commission.","cite":"18 U.S.C. 3553(a)(4)(A)"}]},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)","(c)","(c)(2)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"by":{"0":"21, 1, 10, 35, 37, passim","1":"passim, passim","2":"1, passim"},"q":[{"src":"brief","b":0,"text":"sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission.","cite":"18 U.S.C. § 3582(c)(2)"},{"src":"brief","b":0,"text":"if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission.","cite":"18 U.S.C. § 3582(c)(2)"},{"src":"brief","b":1,"text":"a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission.","cite":"18 U.S.C. 3582(c)(2)"},{"src":"brief","b":1,"text":"based on a sentencing range that has subsequently been lowered by the Sentencing Commission.","cite":"18 U.S.C. 3582(c)(2)"},{"src":"brief","b":2,"text":"sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission.","cite":"18 U.S.C. § 3582(c)(2)"},{"src":"argument","who":"Mr. Fisher","text":"And so we still have a lower guideline range after Amendment 782, which is all that's required to get relief under Section 3582. And I think that adds one other thing I want to say, and it brings me back to Justice Ginsburg's question about the concern about disparities and who gets relief and who doesn't."},{"src":"argument","who":"Mr. Fisher","text":"So, if anything, we would win, but I think out of an abundance of caution in the way that Section 3582 applies, you might just send it back to the district judge, but -"},{"src":"argument","who":"Mr. Fisher","text":"The Court granted a -- a case dealing with Section 3582, but what really happens in this case is -- is -- is everything turns, at least set -- setting aside what we just discussed, but everything in the first instance turns on Section 3553(e)."}]},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)","(b)(1)(B)","(c)(1)","(c)(2)","(b)(1)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, passim, 6, 7, 7","1":"25, 35, 36, 25, 35, 36, 25, 35, 36, 25, 35, 36"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","stext":{"head":"§846. Attempt and conspiracy","paras":[[0,"Any person who attempts or conspires to commit any offense defined in this subchapter shall be subject to the same penalties as those prescribed for the offense, the commission of which was the object of the attempt or conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/846?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"25, 35, 36"}},{"t":"usc","label":"21 U.S.C. § 851","url":"https://www.law.cornell.edu/uscode/text/21/851","by":{"0":"4, 7"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(b)(1)(B)"],"by":{"0":"39","1":"19"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(a)","(a)(2)(B)","(a)(2)(C)","(b)","(c)","(n)","(o)","(u)","(b)(1)","(h)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 20, 28, 34, 35, 36, 21, 34, 34, 16, 27, 31, 32, 34, 1, 36","1":"25, 35, 36, 20, 21, 22, 23, 27, 27, 27","2":"18, 9, 18, 19"},"q":[{"src":"brief","b":0,"text":"assure that the guidelines reflect the general appropriateness of imposing a lower sentence than . . . that established by statute as a minimum sentence, to take into account a defendant’s substantial assistance.","cite":"28 U.S.C. § 994(n)"},{"src":"brief","b":0,"text":"a sentence that is lower than that established by statute as a minimum sentence.","cite":"28 U.S.C. § 994(n)"},{"src":"brief","b":1,"text":"consistent with all pertinent provisions of","cite":"28 U.S.C. 994(b)(1)"},{"src":"brief","b":2,"text":"If the Commission reduces the term of imprisonment recommended in the guidelines applicable to a particular offense or category of offenses, it shall specify in what circumstances . . . the sentences of prisoners serving terms of imprisonment for the offense may be reduced.","cite":"28 U.S.C. § 994(u)"},{"src":"argument","who":"Mr. Fisher","text":"It says: \"Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994.\" So, in other words, that text directs the court straight to the guidelines, not away from the guidelines."},{"src":"argument","who":"Mr. Fisher","text":"And I think what cements this, if I could return the -- the Court to the text that I was referring to at page 3a of the government's brief, it's the sentence -- it's the reference to Section 994 as a whole."},{"src":"argument","who":"Mr. Fisher","text":"And if I could just read you one more time -- I think the language, which hard - Congress could hardly speak more clearly, at page 3a when it says \"Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Commission pursuant to Section 994.\" So the -- so the government -- so Mr."}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"case","label":"Biddle v. Perovich","cite":"274 U.S. 480","y":1927,"id":"scdb/1926-088","sc":1,"by":{"1":"58"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"by":{"1":"38"}},{"t":"case","label":"Florida Dep’t of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"by":{"1":"30, 33"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"‘identical words used in different parts of the same statute’ carry ‘the same meaning.’","cite":"137 S. Ct. 1718, 1723"}]},{"t":"case","label":"IBP, Inc. v. Alvarez","cite":"546 U.S. 21","y":2005,"id":"2005/03-1238","sc":1,"by":{"1":"21"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"by":{"1":"31, 36"},"q":[{"src":"brief","b":1,"text":"[W]hen ‘Congress includes particular language in one section of a statute but omits it in another’—let alone in the very next provision—this Court ‘presume[s]’ that Congress intended a difference in meaning.","cite":"134 S. Ct. 2384, 2390"},{"src":"brief","b":1,"text":"Congress intended a difference in meaning.","cite":"134 S. Ct. at 2390"}]},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"1":"19"}},{"t":"case","label":"Neal v. United States","cite":"516 U.S. 284","y":1996,"id":"1995/94-9088","sc":1,"by":{"1":"23, 28, 52, 53"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"136 S. Ct. 390","y":2015,"id":"2015/13-1067","sc":1,"by":{"1":"44"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"by":{"1":"20, 39"},"q":[{"src":"brief","b":1,"text":"‘sentence sufficient, but not greater than necessary,’ to comply with the sentencing purposes set forth in [18 U.S.C.] 3553(a)(2),","cite":"562 U.S. at 491"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"1":"31, 36"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"by":{"1":"38"}},{"t":"case","label":"Saudi Arabia v. Nelson","cite":"507 U.S. 349","y":1993,"id":"1992/91-522","sc":1,"by":{"1":"44"}},{"t":"case","label":"Schick v. Reed","cite":"419 U.S. 256","y":1974,"id":"1974/73-5677","sc":1,"by":{"1":"58"},"q":[{"src":"brief","b":1,"text":"plenary authority * * * to reduce a penalty in terms of a specified number of years,","cite":"419 U.S. 256, 266"}]},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"by":{"1":"36"}},{"t":"case","label":"Stinson v. United States","cite":"508 U.S. 36","y":1993,"id":"1992/91-8685","sc":1,"by":{"1":"27, 38"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"by":{"1":"21"}},{"t":"case","label":"United States v. A.B.","cite":"529 F.3d 1275","y":2008,"url":"https://www.courtlistener.com/c/F.3d/529/1275/","by":{"1":"29, 39, 40"}},{"t":"case","label":"United States v. Ahlers","cite":"305 F.3d 54","y":2002,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/305/54/","by":{"1":"30, 31, 32"},"q":[{"src":"brief","b":1,"text":"leads inexorably to the conclusion that Congress had different plans in mind for the operation and effect of the two provisions.","cite":"305 F.3d at 58"},{"src":"brief","b":1,"text":"offer no explanation as to why two provisions with such different architecture and such different goals should be deemed to march in lockstep.","cite":"305 F.3d at 59"}]},{"t":"case","label":"United States v. Carter","cite":"595 F.3d 575","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/595/575/","by":{"1":"29"}},{"t":"case","label":"United States v. Casiano","cite":"113 F.3d 420","y":1997,"url":"https://www.courtlistener.com/c/F.3d/113/420/","by":{"1":"37"}},{"t":"case","label":"United States v. Dyke","cite":"718 F.3d 1282","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/718/1282/","by":{"1":"37"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"by":{"1":"31, 32","2":"8"}},{"t":"case","label":"United States v. Fulton","cite":"431 Fed. Appx. 732","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./431/732/","by":{"1":"39"}},{"t":"case","label":"United States v. Grant","cite":"636 F.3d 803","y":2011,"url":"https://www.courtlistener.com/c/F.3d/636/803/","by":{"1":"34"}},{"t":"case","label":"United States v. Hood","cite":"556 F.3d 226","y":2009,"url":"https://www.courtlistener.com/c/F.3d/556/226/","by":{"1":"29"}},{"t":"case","label":"United States v. Jackson","cite":"577 F.3d 1032","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/577/1032/","by":{"1":"29, 39"}},{"t":"case","label":"United States v. Joiner","cite":"727 F.3d 601","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/727/601/","by":{"1":"29","2":"11"}},{"t":"case","label":"United States v. LaBonte","cite":"520 U.S. 751","y":1997,"id":"1996/95-1726","sc":1,"by":{"1":"50","2":"18, 19"},"q":[{"src":"brief","b":2,"text":"to the extent the Commission’s directives conflict with those of Congress, [they] ‘must give way.’","cite":"520 U.S. 751, 757"}]},{"t":"case","label":"United States v. Mills","cite":"613 F.3d 1070","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/613/1070/","by":{"1":"29"}},{"t":"case","label":"United States v. Pepper","cite":"412 F.3d 995","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/412/995/","by":{"1":"37"}},{"t":"case","label":"United States v. Poland","cite":"562 F.3d 35","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/562/35/","by":{"1":"34"}},{"t":"case","label":"United States v. Poole","cite":"550 F.3d 676","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/550/676/","by":{"1":"29"}},{"t":"case","label":"United States v. Richardson","cite":"521 F.3d 149","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/521/149/","by":{"1":"42"}},{"t":"case","label":"United States v. Roa-Medina","cite":"607 F.3d 255","y":2010,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/607/255/","by":{"1":"29, 40"}},{"t":"case","label":"United States v. Rublee","cite":"655 F.3d 835","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/835/","by":{"1":"39"}},{"t":"case","label":"United States v. Savani","cite":"733 F.3d 56","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/733/56/","by":{"1":"41, 43"}},{"t":"case","label":"United States v. Spinks","cite":"770 F.3d 285","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/770/285/","by":{"1":"8, 17, 32"}},{"t":"case","label":"United States v. Tadio","cite":"663 F.3d 1042","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/663/1042/","by":{"1":"34"}},{"t":"case","label":"United States v. Williams","cite":"474 F.3d 1130","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/474/1130/","by":{"1":"16, 30, 32"},"q":[{"src":"brief","b":1,"text":"‘based exclusively on assistance- related considerations.’","cite":"474 F.3d 1130, 1131"},{"src":"brief","b":1,"text":"specifies precisely how a sentencing court’s authority is limited.","cite":"474 F.3d at 1132"}]},{"t":"case","label":"United States v. Williams","cite":"551 F.3d 182","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/551/182/","by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"consider other factors, including those in § 3553(a), to decide whether to depart to that full extent.","cite":"551 F.3d 182, 186"}]},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"33"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)(2)"],"by":{"1":"44"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","by":{"1":"19"}},{"t":"law","label":"Pub. L. No. 99-217","url":"https://www.govinfo.gov/link/statute/99/1728","by":{"1":"34"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1985","by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 3552","url":"https://www.law.cornell.edu/uscode/text/18/3552","subs":["(a)"],"by":{"1":"5"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"by":{"2":"8"}},{"t":"case","label":"Baldwin v. Reese","cite":"541 U.S. 27","y":2004,"id":"2003/02-964","sc":1,"by":{"2":"21"}},{"t":"case","label":"Bhd. of R. Trainmen v. Balt. & Ohio R. Co.","cite":"331 U.S. 519","y":1947,"id":"scdb/1946-111","sc":1,"by":{"2":"6"}},{"t":"case","label":"Duehay v. Thompson","cite":"223 F. 305","y":1915,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F./223/305/","by":{"2":"21"}},{"t":"case","label":"Gutierrez v. Ada","cite":"528 U.S. 250","y":2000,"id":"1999/99-51","sc":1,"by":{"2":"8"},"q":[{"src":"argument","who":"Mr. Fisher","text":"Gutierrez, the judge actually said - partly because he didn't think the guidelines properly measured the offense. So, if anything, we would win, but I think out of an abundance of caution in the way that Section 3582 applies, you might just send it back to the district judge, but -"}]},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"by":{"2":"8"}},{"t":"case","label":"United States v. Benz","cite":"282 U.S. 304","y":1931,"id":"scdb/1930-114","sc":1,"by":{"2":"21"}},{"t":"case","label":"United States v. Calle","cite":"796 F. Supp. 853","y":1992,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp./796/853/","by":{"2":"6"}},{"t":"case","label":"United States v. Parral-Dominguez","cite":"794 F.3d 440","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/440/","by":{"2":"17"}},{"t":"case","label":"United States v. Phillips","cite":"382 F.3d 489","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/382/489/","by":{"2":"7"}},{"t":"case","label":"United States v. Stewart","cite":"306 F.3d 295","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/306/295/","by":{"2":"11"}},{"t":"rule","label":"Fed. R. Crim. P. 35","url":"https://www.law.cornell.edu/rules/frcrmp/rule_35","subs":["(b)"],"by":{"2":"6"}}]};